    const value = normalize(alias);
    if (value.startsWith(needle)) return 40;
    if (value.includes(needle)) return 30;
  }
  return 0;
}

function normalize(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "");
}

