@import "tailwindcss";

@theme {
  --font-sans:
    ui-sans-serif, -apple-system, "SF Pro Text", "Segoe UI", Inter, Roboto, system-ui, sans-serif;
  --font-mono: ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Consolas, monospace;

  /* Surfaces */
  --color-canvas: #06070a;
  --color-panel: #0c0e13;
  --color-panel-soft: #11141b;
  --color-line: #1e222c;
  --color-line-soft: #171a22;

  /* Type */
  --color-ink: #e9edf5;
  --color-mute: #949db1;
  --color-faint: #576073;

  /* Semantics */
  --color-ref: #f7b955;
  --color-overlap: #34d399;
  --color-alert: #fb7185;
}

@layer base {
  html {
    color-scheme: dark;
    -webkit-tap-highlight-color: transparent;
  }

  body {
    background-color: var(--color-canvas);
    color: var(--color-ink);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    text-rendering: optimizeLegibility;
    overscroll-behavior-y: none;
  }

  /* One ambient light source, top-left, so the page has depth without noise. */
  body::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    z-index: 0;
    background:
      radial-gradient(60rem 40rem at 12% -10%, rgb(52 211 153 / 0.07), transparent 60%),
      radial-gradient(50rem 34rem at 88% 0%, rgb(247 185 85 / 0.05), transparent 55%);
  }

  :focus-visible {
    outline: 2px solid color-mix(in oklab, var(--color-overlap) 75%, white);
    outline-offset: 2px;
    border-radius: 4px;
  }

  ::selection {
    background: color-mix(in oklab, var(--color-overlap) 35%, transparent);
  }
}

@utility tnum {
  font-variant-numeric: tabular-nums;
  font-feature-settings: "tnum";
}

/* Scrollbars inside the grid regions: present, but quiet. */
@utility scroll-quiet {
  scrollbar-width: thin;
  scrollbar-color: var(--color-line) transparent;

  &::-webkit-scrollbar {
    height: 8px;
    width: 8px;
  }
  &::-webkit-scrollbar-thumb {
    background: var(--color-line);
    border-radius: 999px;
  }
  &::-webkit-scrollbar-track {
    background: transparent;
  }
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@utility animate-rise {
  animation: rise 140ms cubic-bezier(0.22, 1, 0.36, 1);
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

