import type { Mode } from "../lib/schedule";

const SWATCHES = [
  { label: "Sleeping", className: "bg-white/[0.05] ring-1 ring-inset ring-white/5" },
  { label: "Awake", className: "bg-white/[0.14] ring-1 ring-inset ring-white/10" },
