  hour,
  format,
  overlap,
  now,
}: {
  hour: number;
  format: TimeFormat;
  overlap: boolean;
  now: boolean;
}) {
  const label = formatClock(hour, 0, format);
  return (
    <div
      className={cx(
        "tnum relative z-10 flex h-7 items-baseline justify-center rounded-md text-[11px]",
