    // mobile = cities across, hours down: DOM-consecutive cells share a row (one per city)
    cellsPerRow: sameRow.length,
    consecutiveShareRow: Math.abs(box(cells[0]).top - box(cells[1]).top) < 2 && box(cells[1]).left > box(cells[0]).left,
    columnsAligned: [0, 3, 6].every((i) => Math.abs(box(cells[i]).left - box(cells[i + 3 * 3]).left) < 1),
    bodyScrollsX: document.documentElement.scrollWidth > window.innerWidth + 1,
    labels: cells.slice(0, 3).map((c) => c.getAttribute("aria-label")),
  };
}, SEL), null, 2));
console.log(await saveScreenshot(await page.screenshot({ fullPage: true }), "tz-mobile.png"));

// interactions still work on mobile
await page.getByRole("button", { name: "Geneva", exact: true }).click();
await page.waitForTimeout(300);
console.log("MOBILE PROMOTE:", JSON.stringify(await page.evaluate(() => JSON.parse(localStorage.getItem("timezone-overlap:v1")).cityIds)));
console.log(await saveScreenshot(await page.screenshot(), "tz-mobile-top.png"));
console.log("ERRORS:", JSON.stringify(errors));
EOF

